  it('keeps the usage an earlier round reported when a later round reports none', async () => {
    const usage: UsageMetadata = {inputTokens: 11, outputTokens: 3, totalTokens: 14};
    let seen: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, reported) => {
        seen = reported;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage}],
      namesConstraint: response.result.includes('enum'),
    }).toEqual({
      namesProperty: true,
      namesConstraint: true,
    });
  });

  // @spec specs/hal-engine-tool-input-validation/spec.md#2
  it('does not log or return a rejected property value', async () => {
    const registry = new ToolRegistry();
    const secret = 'private-location-4821';
    const logLine = jest.spyOn(console, 'log').mockImplementation(() => undefined);
    registerWeatherTool(registry, {type: 'object', properties: {location: {type: 'number'}}}, async () => 'sunny');

    const response = await registry.execute('weather', {location: secret as unknown as number});

    expect({
      responseContainsSecret: response.result.includes(secret),
      loggedSecret: logLine.mock.calls.some(call => call.some(value => String(value).includes(secret))),
    }).toEqual({
      responseContainsSecret: false,
      loggedSecret: false,
    });
    logLine.mockRestore();
  });
});
